const T = context.vars.totals;
for (const name in T) {
  const line = output.split('\n').find(l => l.startsWith('- ' + name + ':'));
  const m = line && line.match(/\$([\d,]+(?:\.\d+)?)/);
  if (!m || Math.abs(parseFloat(m[1].replace(/,/g, '')) - T[name]) > 1) return false;
}
return true;
